.what-we-do { background: var(--color-neutral-light); }

.tabs-container { display: grid; grid-template-columns: 300px 1fr; gap: 3rem; }

.tab-list { display: flex; flex-direction: column; gap: 0.25rem; }

.tab-btn {
  display: flex; align-items: center; justify-content: space-between;
  padding: 1.15rem 1.5rem; font-size: 1rem; font-weight: 500; color: var(--color-text-secondary);
  background: transparent; border-left: 3px solid transparent; border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  transition: all var(--transition-fast); text-align: left;
}
.tab-btn:hover { background: rgba(0,63,45,0.04); color: var(--color-primary); }
.tab-btn.active {
  background: var(--color-white); color: var(--color-primary); font-weight: 600;
  border-left-color: var(--color-accent); box-shadow: var(--shadow-sm);
}
.tab-btn .tab-arrow { opacity: 0; transition: all var(--transition-fast); }
.tab-btn.active .tab-arrow { opacity: 1; }

.tab-panels { position: relative; min-height: 300px; }

.tab-panel {
  position: absolute; inset: 0; opacity: 0; visibility: hidden;
  transition: opacity var(--transition-base), visibility var(--transition-base);
  background: var(--color-white); border-radius: var(--radius-lg);
  padding: 3rem; box-shadow: var(--shadow-md);
  display: flex; flex-direction: column; justify-content: center;
}
.tab-panel.active { opacity: 1; visibility: visible; position: relative; }

.tab-panel-icon {
  width: 56px; height: 56px; border-radius: var(--radius-sm);
  background: linear-gradient(135deg, var(--color-primary), var(--color-primary-light));
  display: flex; align-items: center; justify-content: center; color: var(--color-white);
  font-size: 1.5rem; margin-bottom: 1.5rem;
}

.tab-panel h3 { font-family: var(--font-heading); font-size: 1.5rem; margin-bottom: 0.75rem; }
.tab-panel p { color: var(--color-text-secondary); line-height: 1.7; margin-bottom: 1.5rem; }

/* ============================================================
   NEWSLETTER CTA
   ============================================================ */
.newsletter-cta {
  background: var(--color-secondary); color: var(--color-white); padding: 4rem 0; text-align: center;
}
.newsletter-cta h2 { color: var(--color-white); }
.newsletter-cta p { color: rgba(255,255,255,0.8); margin: 0.75rem auto 2rem; max-width: 500px; }

.newsletter-form {
  display: flex; gap: 0.75rem; max-width: 480px; margin: 0 auto;
}
.newsletter-form input {
  flex: 1; padding: 0.85rem 1.25rem; font-size: 0.95rem; border: 2px solid rgba(255,255,255,0.2);
  border-radius: var(--radius-sm); background: rgba(255,255,255,0.1); color: var(--color-white);
  outline: none; transition: border-color var(--transition-fast);
}
.newsletter-form input::placeholder { color: rgba(255,255,255,0.5); }
.newsletter-form input:focus { border-color: var(--color-accent); }

/* ============================================================
   LATEST INSIGHTS
   ============================================================ */
.latest-insights { background: var(--color-white); }

.insights-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem;
}

.insight-card-large {
  background: var(--color-white); border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm); overflow: hidden; transition: all var(--transition-base);
}
.insight-card-large:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }

.insight-card-img {
  width: 100%; aspect-ratio: 16/10;
  background: linear-gradient(135deg, var(--color-neutral), #D0D0D0);
  display: flex; align-items: center; justify-content: center; color: var(--color-text-light);
  font-size: 0.85rem;
}

.insight-card-body { padding: 1.5rem; }

.insight-card-body .tag { margin-bottom: 0.75rem; }

.insight-card-body h3 { font-family: var(--font-body); font-size: 1.05rem; font-weight: 600; line-height: 1.4; margin-bottom: 0.5rem; }

.insight-card-body .date { font-size: 0.8rem; color: var(--color-text-light); }

/* ============================================================
   COMMITMENT PILLARS
   ============================================================ */
.commitment { background: var(--color-neutral-light); }

.commitment-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 1.5rem;
}

.commitment-card {
  background: var(--color-white); border-radius: var(--radius-md);
  padding: 2rem; box-shadow: var(--shadow-sm); transition: all var(--transition-base);
}
.commitment-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }

.commitment-card-icon {
  width: 48px; height: 48px; border-radius: var(--radius-sm);
  background: rgba(0,63,45,0.08); display: flex; align-items: center; justify-content: center;
  color: var(--color-primary); font-size: 1.25rem; margin-bottom: 1.25rem;
}

.commitment-card h3 { font-family: var(--font-heading); font-size: 1.15rem; margin-bottom: 0.75rem; }
.commitment-card p { font-size: 0.9rem; color: var(--color-text-secondary); line-height: 1.6; margin-bottom: 1.25rem; }

/* ============================================================
   SERVICES OVERVIEW — Capability Cards
   ============================================================ */
.services-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem;
}

.service-card {
  background: var(--color-white); border-radius: var(--radius-md);
  padding: 2rem; box-shadow: var(--shadow-sm); transition: all var(--transition-base);
  border-top: 3px solid transparent; display: flex; flex-direction: column;
}
.service-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); border-top-color: var(--color-accent); }

.service-card-icon {
  width: 52px; height: 52px; border-radius: var(--radius-sm);
  background: linear-gradient(135deg, var(--color-primary), var(--color-primary-light));
  display: flex; align-items: center; justify-content: center; color: var(--color-white);
  font-size: 1.35rem; margin-bottom: 1.25rem; flex-shrink: 0;
}

.service-card h3 { font-family: var(--font-heading); font-size: 1.15rem; margin-bottom: 0.75rem; }
.service-card p { font-size: 0.92rem; color: var(--color-text-secondary); line-height: 1.65; margin-bottom: 1.5rem; flex: 1; }
.service-card .btn-link { margin-top: auto; }

/* ============================================================
   CAPABILITIES GRID (Detail Pages)
   ============================================================ */
.capabilities-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.25rem;
}

.capability-card {
  background: var(--color-white); border-radius: var(--radius-md);
  padding: 1.75rem; box-shadow: var(--shadow-sm); transition: all var(--transition-base);
  border-left: 3px solid transparent;
}
.capability-card:hover { box-shadow: var(--shadow-md); border-left-color: var(--color-accent); }

.capability-card h4 { font-family: var(--font-heading); font-size: 1.05rem; margin-bottom: 0.5rem; color: var(--color-secondary); }
.capability-card p { font-size: 0.88rem; color: var(--color-text-secondary); line-height: 1.6; }

/* ============================================================
   FEATURED PARTNERS CAROUSEL
   ============================================================ */
.carousel-section { background: var(--color-neutral-light); position: relative; }

.carousel-container { position: relative; overflow: hidden; }

.carousel-track {
  display: flex; transition: transform var(--transition-slow);
}

.carousel-slide {
  flex: 0 0 100%; padding: 2rem 0;
}

.partner-card {
  background: var(--color-white); border-radius: var(--radius-lg);
  padding: 3rem; text-align: center; max-width: 600px; margin: 0 auto;
  box-shadow: var(--shadow-md);
}

.partner-card .partner-logo {
  width: 80px; height: 80px; border-radius: 50%;
  background: linear-gradient(135deg, var(--color-neutral), #CCC);
  margin: 0 auto 1.5rem; display: flex; align-items: center; justify-content: center;
  font-size: 0.7rem; color: var(--color-text-light);
}

.partner-card blockquote { font-family: var(--font-heading); font-size: 1.2rem; font-style: italic; color: var(--color-text); margin-bottom: 1.5rem; line-height: 1.6; }
.partner-card cite { font-weight: 600; font-style: normal; color: var(--color-primary); }

.carousel-controls {
  display: flex; align-items: center; justify-content: center; gap: 1rem; margin-top: 1.5rem;
}

.carousel-btn {
  width: 44px; height: 44px; border-radius: 50%; display: flex; align-items: center; justify-content: center;
  border: 2px solid var(--color-border); background: var(--color-white);
  font-size: 1.1rem; color: var(--color-text); transition: all var(--transition-fast);
}
.carousel-btn:hover { border-color: var(--color-primary); color: var(--color-primary); }

.carousel-dots { display: flex; gap: 0.5rem; }
.carousel-dot {
  width: 10px; height: 10px; border-radius: 50%; background: var(--color-border);
  transition: all var(--transition-fast);
}
.carousel-dot.active { background: var(--color-primary); width: 28px; border-radius: 999px; }

/* ============================================================
   DEAL FLOW CTA
   ============================================================ */
.deal-flow { background: var(--color-secondary); color: var(--color-white); padding: 4rem 0; text-align: center; }
.deal-flow h2 { color: var(--color-white); margin-bottom: 0.75rem; }
.deal-flow p { color: rgba(255,255,255,0.8); max-width: 600px; margin: 0 auto 2rem; font-size: 1.05rem; line-height: 1.7; }

/* ============================================================
   FEATURED TOPICS SIDEBAR
   ============================================================ */
.featured-topics-section { padding: 4rem 0; }

.topics-layout { display: grid; grid-template-columns: 1fr 320px; gap: 3rem; align-items: start; }

.topics-list { background: var(--color-neutral-light); border-radius: var(--radius-md); padding: 1.5rem; }

.topics-list h4 { font-family: var(--font-body); font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.08em; color: var(--color-text-light); margin-bottom: 1rem; }

.topics-list li { margin-bottom: 0.5rem; }

.topics-list a {
  display: block; padding: 0.6rem 0.75rem; font-size: 0.9rem; font-weight: 500;
  color: var(--color-text-secondary); border-radius: var(--radius-sm); transition: all var(--transition-fast);
}
.topics-list a:hover { background: var(--color-white); color: var(--color-primary); }

/* ============================================================
   TESTIMONIAL / QUOTE
   ============================================================ */
.testimonial-section { background: var(--color-white); }

.testimonial { max-width: 700px; margin: 0 auto; text-align: center; }

.testimonial blockquote {
  font-family: var(--font-heading); font-size: clamp(1.2rem, 2vw, 1.5rem); font-style: italic;
  color: var(--color-text); line-height: 1.6; margin-bottom: 1.5rem;
  position: relative; padding: 2rem;
}

.testimonial blockquote::before {
  content: '"'; font-size: 5rem; font-family: var(--font-heading);
  color: var(--color-accent); position: absolute; top: -1rem; left: 50%;
  transform: translateX(-50%); line-height: 1; opacity: 0.3;
}

.testimonial cite { font-weight: 600; color: var(--color-primary); font-style: normal; }
.testimonial cite span { display: block; font-weight: 400; font-size: 0.85rem; color: var(--color-text-light); margin-top: 0.25rem; }

/* ============================================================
   RELATED CONTENT
   ============================================================ */
.related-section { background: var(--color-neutral-light); }

.related-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; }

.related-card {
  background: var(--color-white); border-radius: var(--radius-md);
  padding: 1.5rem; box-shadow: var(--shadow-sm); transition: all var(--transition-base);
}
.related-card:hover { box-shadow: var(--shadow-md); }

.related-card h4 { font-family: var(--font-body); font-size: 0.95rem; font-weight: 600; margin-bottom: 0.5rem; }
.related-card p { font-size: 0.85rem; color: var(--color-text-secondary); }
.related-card .btn-link { margin-top: 0.75rem; font-size: 0.85rem; }

/* ============================================================
   PARTNERSHIP HIGHLIGHT
   ============================================================ */
.partnership-highlight { background: var(--color-white); }

.partnership-card {
  background: linear-gradient(135deg, var(--color-neutral-light) 0%, var(--color-white) 100%);
  border-radius: var(--radius-lg); padding: 3rem; box-shadow: var(--shadow-md);
  display: grid; grid-template-columns: 1fr 1fr; gap: 3rem; align-items: center;
}

.partnership-stats { display: flex; gap: 2rem; margin-top: 1.5rem; }

.stat { text-align: center; }
.stat-number { font-family: var(--font-heading); font-size: 2.25rem; font-weight: 700; color: var(--color-primary); }
.stat-label { font-size: 0.85rem; color: var(--color-text-secondary); margin-top: 0.25rem; }

.partnership-visual .placeholder-img {
  width: 100%; aspect-ratio: 16/10; border-radius: var(--radius-lg);
  background: linear-gradient(135deg, var(--color-neutral), #CCC);
  display: flex; align-items: center; justify-content: center; color: var(--color-text-light);
}

/* ============================================================
   INTRO STATEMENT
   ============================================================ */
.intro-statement { background: var(--color-white); }
.intro-statement .container { max-width: 800px; text-align: center; }
.intro-statement .section-title { text-align: center; }
.intro-statement p { font-size: 1.1rem; color: var(--color-text-secondary); line-height: 1.8; }

/* Property Types CTA */
.property-types-cta { background: var(--color-white); }
.property-types-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 1rem; }

.property-type-card {
  background: var(--color-neutral-light); border-radius: var(--radius-md);
  padding: 1.5rem; text-align: center; transition: all var(--transition-base);
}
.property-type-card:hover { background: var(--color-primary); color: var(--color-white); }
.property-type-card:hover p { color: rgba(255,255,255,0.8); }

.property-type-card h4 { font-family: var(--font-heading); font-size: 1rem; margin-bottom: 0.25rem; }
.property-type-card p { font-size: 0.8rem; color: var(--color-text-light); }

/* ============================================================
   FOOTER
   ============================================================ */
.site-footer {
  background: var(--color-navy); color: rgba(255,255,255,0.7); padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid; grid-template-columns: 2fr 1fr 1fr; gap: 3rem; margin-bottom: 3rem;
}

.footer-brand .logo { color: var(--color-white); margin-bottom: 1rem; }
.footer-brand p { font-size: 0.9rem; line-height: 1.7; max-width: 360px; }

.footer-nav h5 {
  font-family: var(--font-body); font-size: 0.75rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.08em; color: var(--color-white); margin-bottom: 1rem;
}

.footer-nav li { margin-bottom: 0.5rem; }
.footer-nav a { font-size: 0.9rem; transition: color var(--transition-fast); }
.footer-nav a:hover { color: var(--color-accent); }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1); padding-top: 2rem;
  display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 1rem;
  font-size: 0.85rem;
}

.footer-bottom-links { display: flex; gap: 1.5rem; }
.footer-bottom-links a:hover { color: var(--color-accent); }

/* ============================================================
   RESPONSIVE
   ============================================================ */

/* Tablet: 768px - 1024px */
@media (max-width: 1024px) {
  .featured-insights-grid { grid-template-columns: repeat(2, 1fr); }
  .insights-grid { grid-template-columns: repeat(2, 1fr); }
  .commitment-grid { grid-template-columns: repeat(2, 1fr); }
  .services-grid { grid-template-columns: repeat(2, 1fr); }
  .capabilities-grid { grid-template-columns: repeat(2, 1fr); }
  .tabs-container { grid-template-columns: 240px 1fr; gap: 1.5rem; }
  .topics-layout { grid-template-columns: 1fr; }
  .partnership-card { grid-template-columns: 1fr; gap: 2rem; }
  .property-types-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .about-grid { grid-template-columns: 1fr; gap: 2rem; }
}

/* Mobile: < 768px */
@media (max-width: 768px) {
  .container { padding: 0 1.25rem; }
  .section { padding: 3.5rem 0; }

  /* Header */
  .main-nav { display: none; }
  .mobile-toggle { display: flex; }

  /* Hero */
  .hero { min-height: 70vh; }
  .hero-page { min-height: 40vh; }

  /* Grids */
  .featured-insights-grid, .insights-grid, .commitment-grid,
  .services-grid, .capabilities-grid, .related-grid,
  .footer-grid { grid-template-columns: 1fr; }

  .tabs-container { grid-template-columns: 1fr; }

  .tab-list { flex-direction: row; overflow-x: auto; padding-bottom: 0.5rem; }
  .tab-btn { white-space: nowrap; border-left: none; border-bottom: 3px solid transparent; border-radius: var(--radius-sm) var(--radius-sm) 0 0; padding: 0.75rem 1.25rem; }
  .tab-btn.active { border-left-color: transparent; border-bottom-color: var(--color-accent); box-shadow: none; }

  .newsletter-form { flex-direction: column; }
  .hero-actions { flex-direction: column; }
  .property-types-grid { grid-template-columns: repeat(2, 1fr); }
  .partner-card { padding: 2rem; }
  .tab-panel { padding: 2rem; }

  .announcement-inner { flex-direction: column; gap: 1rem; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .footer-bottom-links { justify-content: center; }
}
